import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-112: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short112', durationInSeconds: 40.8, fps: 30, width: 1080, height: 1920 };



const B1 = secToFrame(4.4);
const B2 = secToFrame(10.9);
const B3 = secToFrame(16.9);
const B4 = secToFrame(23.0);
const B5 = secToFrame(28.2);
const CTA = secToFrame(35.6);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);


const Short112: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-112/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="10-CENT AI TIER" lines={[{ text: 'OPENAI + ANTHROPIC' }, { text: 'GOOGLE: 10¢', accent: true }]} />
      </FadeOut>
      <FadeOut at={B2}>
        <ToolCard name="GPT-6 Luna" tagline="OpenAI." chip="10¢ IN" at={B1 + 4}>
          <Panel>
            <Line k="Input" v="$0.10" good />
            <Line k="Output" v="$0.50" good />
            <Line k="Cached" v="$0.01" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3}>
        <ToolCard name="Claude Haiku 5.5" tagline="Anthropic, up to 100K prompts." chip="10¢ IN" at={B2 + 4}>
          <Panel>
            <Line k="Input" v="$0.10" good />
            <Line k="Output" v="$0.50" good />
            <Line k="Cached" v="$0.01" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4}>
        <ToolCard name="Past 100K tokens" tagline="Haiku input jumps." chip="50¢ IN" at={B3 + 4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Input" v="$0.50" bad />
            <Line k="Output" v="$2.50" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5}>
        <ToolCard name="Gemini 2.5 Flash-Lite" tagline="Google." chip="40¢ OUT" at={B4 + 4} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="Input" v="$0.10" good />
            <Line k="Output" v="$0.40" good />
            <Line k="Cached" v="$0.01" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA}>
        <ToolCard name="Cached input" tagline="One cent on all three." chip="1¢" at={B5 + 4}>
          <Panel>
            <Line k="GPT-6 Luna" v="$0.01" good />
            <Line k="Haiku 5.5" v="$0.01" good />
            <Line k="Flash-Lite" v="$0.01" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-112/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="10-CENT AI TIER" lines={[{ text: 'OPENAI + ANTHROPIC' }, { text: 'GOOGLE: 10¢', accent: true }]} />
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short112;
